 const body=rows.length?`<div class="bomSimple">${rows.map(x=>`<div class="bomSimpleRow"><div><b>${esc(x.mark||"—")}</b><span>${esc(x.name||"Без наименования")}</span></div><div class="bomCount"><small>Смонтировано</small><b>${fmt(x.d)} / ${fmt(x.q)}</b><em>Осталось ${fmt(x.left)}</em></div></div>`).join("")}</div>`:'<div class="empty">Нет строк для выбранного фильтра</div>';
 return card("Ведомость марок",`<div class="bomHeadline"><div><small>ВСЕГО</small><b>${fmt(total)}</b></div><div><small>СМОНТИРОВАНО</small><b>${fmt(done)}</b></div><div><small>ОСТАЛОСЬ</small><b>${fmt(Math.max(0,total-done))}</b></div></div>${filters}${body}`)
