function home(){return (state.companyLogo?`<div class="reportLogo"><img src="${state.companyLogo}" alt="Логотип компании"></div>`:"")+(state.companyName?card("Организация",`<b class="companyReportName">${esc(state.companyName)}</b>`):"")+card("Дата отчёта",`<b>${esc(state.reportDate||"—")}</b> &nbsp; Температура: ${esc(state.weather?.temp||"—")} °C &nbsp; Ветер: ${esc(state.weather?.wind||"—")} м/с &nbsp; Осадки: ${esc(state.weather?.precip||"—")}`)+(sectionOn("photos")?photoReportView():"")+(sectionOn("summary")?summary():"")+(sectionOn("bom")?bomView():"")+(sectionOn("responsibles")?card("Ответственные лица",table(arr("responsibles"),[["ФИО",r=>r.name||r.fio],["Должность","position"]])):"")+(sectionOn("workers")?card("Работники",table(arr("workers"),[["ФИО",r=>r.name||r.fio],["Должность","position"]])):"")+(sectionOn("equipment")?card("Машины и механизмы",table(arr("equipment"),[["Наименование",r=>r.name||r.title],["Количество",r=>r.qty||r.quantity]])):"")+(sectionOn("works")?groupedWorksView():"")+(sectionOn("invoices")?groupedInvoicesView():"")+(sectionOn("dynamics")?dynamicsView():"")+(sectionOn("deadlines")?ganttView():"")+(sectionOn("calendar")?multiCalendarView():"")+(sectionOn("penalties")?penaltiesView():"")}
function management(){
 let b=`<div class="manageTabs">${manageViews.map(x=>`<button data-mv="${x[0]}" class="${manageView===x[0]?"active":""}"><i>${x[1]}</i>${x[2]}</button>`).join("")}</div>`;
 if(manageView==="object") b+=card("Объект",`<div class="grid objectTop"><div class="field"><label>Наименование объекта</label><textarea data-root="object">${esc(state.object||state.objectName||"")}</textarea></div><div class="field"><label>Адрес</label><textarea data-root="address">${esc(state.address)}</textarea></div><div class="field"><label>Заказчик</label><textarea data-root="client">${esc(state.client||state.customer||"")}</textarea></div></div><div class="clearReportBox"><b>Очистка отчёта</b><span>Удаляет введённые данные по работам, поставке, срокам, людям, технике, фото, актированным дням и штрафам. Объект и компания сохраняются.</span><button class="danger" data-clear-report>Очистить данные отчёта</button></div>`)+card("Разделы отчёта",`<div class="sectionToggles">${reportSectionDefs.map(([k,nm])=>`<label><input type="checkbox" data-section="${k}" ${sectionOn(k)?"checked":""}> ${nm}</label>`).join("")}</div><p class="hint">Отключённые разделы не показываются в общем отчёте, HTML и PDF.</p>`)+card("Компания",`<div class="grid companySettings"><div class="field"><label>Название фирмы</label><input data-root="companyName" value="${esc(state.companyName||"")} " placeholder="Введите название организации"></div></div>`)+card("Логотип компании",`<div class="logoEditor">${state.companyLogo?`<img src="${state.companyLogo}" alt="Логотип">`:`<div class="logoEmpty">Логотип не загружен</div>`}<div><button class="btn" data-logo-load>Загрузить логотип</button>${state.companyLogo?`<button class="danger logoRemove" data-logo-remove>Удалить</button>`:""}<p class="hint">PNG, JPG/JPEG или WebP. Логотип сохраняется вместе с базой и резервной копией.</p></div></div>`);
 if(manageView==="types") b+=card("Виды работ",rowEditor("workTypes",[["Наименование","name"]]));
 if(manageView==="tasks") b+=card("Задачи — объёмы согласно проекту",rowEditor("tasks",[["Вид работ","type","worktype"],["Шифр проекта","code"],["Проектный объём","qty","number"],["Ед. измерения","unit","unit"]])+arr("tasks").map((t,i)=>`<div class="bomAttach"><b>${esc(t.type||"Задача")} · ${esc(t.code||"без шифра")}</b><span>${(t.bom||[]).length?("Ведомость: "+t.bom.length+" марок"+(t.bomName?" · "+esc(t.bomName):"")):"Ведомость не загружена"}</span><button class="btn" data-bom-import="${i}">${(t.bom||[]).length?"Заменить Excel":"Загрузить Excel"}</button></div>`).join("")+'<p class="hint">Excel: Марка | Наименование | Количество | Вес 1 ед. | Общий вес. Ведомость привязывается к выбранной задаче.</p>');
 if(manageView==="reportInfo") b+=card("Дата отчёта и погода",`<div class="grid"><div class="field"><label>Дата</label><input type="date" data-root="reportDate" value="${esc(state.reportDate)}"></div><div class="field"><label>Температура °C</label><input data-weather="temp" value="${esc(state.weather?.temp)}"></div><div class="field"><label>Ветер м/с</label><input data-weather="wind" value="${esc(state.weather?.wind)}"></div><div class="field"><label>Осадки</label><input data-weather="precip" value="${esc(state.weather?.precip)}"></div></div>`); if(manageView==="photos") b+=card("Фотоотчёт",`<div class="photoTools"><button class="btn" data-photo-add>+ Добавить фото</button><button class="danger" data-photo-clear>Очистить фото</button></div><div class="photoGrid editPhotos">${arr("reportPhotos").map((p,i)=>`<div><img src="${typeof p==="string"?p:(p.data||p.url||"")}"><button class="danger" data-photo-del="${i}">×</button></div>`).join("")}</div>`);
 const configs={deadlines:[["Работа","type","worktype"],["Шифр","code","projectcode"],["Начало","start","date"],["Окончание","end","date"]],works:[["Дата","date","date"],["Работа","type","worktype"],["Шифр","code","projectcode"],["Марка","mark","bommark"],["Наименование","name","readonly"],["Вес 1 ед.","weight1","readonly"],["Остаток","remaining","readonly"],["Количество","qty","number"],["Общий вес","totalWeight","readonly"],["Ед.","unit","readonly"]],invoices:[["Дата","date","date"],["№ накладной","number"],["Работа","type","worktype"],["Шифр","code","projectcode"],["Марка","mark","bommark"],["Количество","qty","number"],["Ед.","unit","readonly"]],workers:[["ФИО","name"],["Должность","position","position"]],responsibles:[["ФИО","name"],["Должность","position","position"]],equipment:[["Наименование","name"],["Количество","qty","number"]],acted:[["Дата","date","date"],["Причина","reason"],["Значение","value"],["Время","time","time"]],penalties:[["Дата","date","date"],["Описание","text"],["Сумма","amount","number"]]};
 const keys={deadlines:"deadlines",works:"workDays",invoices:"invoices",workers:"workers",responsibles:"responsibles",equipment:"equipment",acted:"actedDays",penalties:"penalties"};
 if(configs[manageView]) b+=card(manageViews.find(x=>x[0]===manageView)[2],rowEditor(keys[manageView],configs[manageView]));
 return b;
}
function money(v){return new Intl.NumberFormat("ru-RU",{maximumFractionDigits:2}).format(n(v))+" ₸"}
function financeContractTotal(c){const base=n(c.qty)*n(c.price),vat=n(c.vatRate),vatAmount=base*vat/100;return {base,vatAmount,total:base+vatAmount}}
function financeClosedQty(contract){return arr("financeActs").filter(a=>(a.contract||"")===(contract||"")).reduce((z,a)=>z+n(a.qty),0)}
function financeActAmount(a){if(n(a.amount)>0)return n(a.amount);const c=arr("financeContracts").find(x=>(x.contract||"")===(a.contract||""));if(!c)return 0;return n(a.qty)*n(c.price)*(1+n(c.vatRate)/100)}
async function hashPassword(v){const b=await crypto.subtle.digest("SHA-256",new TextEncoder().encode(v));return [...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,"0")).join("")}
async function unlockFinance(){
 if(financeUnlocked)return true;
 if(!state.financePasswordHash){const p=prompt("Создайте пароль для раздела «Финансы»:");if(!p)return false;const p2=prompt("Повторите пароль:");if(p!==p2){alert("Пароли не совпадают.");return false}state.financePasswordHash=await hashPassword(p);financeUnlocked=true;await save(true);return true}
 const p=prompt("Введите пароль раздела «Финансы»:");if(!p)return false;
 if(await hashPassword(p)!==state.financePasswordHash){alert("Неверный пароль.");return false}
 financeUnlocked=true;return true
}
function financeCharts(){
 const cs=arr("financeContracts"),acts=arr("financeActs");
 if(!cs.length)return "";
 const rows=cs.map(c=>{const total=financeContractTotal(c).total,closed=acts.filter(a=>(a.contract||"")===(c.contract||"")).reduce((z,a)=>z+financeActAmount(a),0),left=Math.max(0,total-closed),pct=total?Math.min(100,closed/total*100):0;return {name:c.contract||c.work||"Договор",total,closed,left,pct}});
 const mx=Math.max(1,...rows.map(x=>x.total));
 const bars=rows.map(x=>`<div class="finChartRow"><div class="finChartName"><b>${esc(x.name)}</b><span>${x.pct.toFixed(1)}%</span></div><div class="finTrack" title="Договор: ${money(x.total)}"><i class="finClosed" style="width:${x.closed/mx*100}%"></i><i class="finLeft" style="width:${x.left/mx*100}%"></i></div><div class="finLegend"><span>Закрыто: <b>${money(x.closed)}</b></span><span>Остаток: <b>${money(x.left)}</b></span><span>Договор: <b>${money(x.total)}</b></span></div></div>`).join("");
 const byDate={};acts.filter(a=>a.date).sort((a,b)=>String(a.date).localeCompare(String(b.date))).forEach(a=>{byDate[a.date]=(byDate[a.date]||0)+financeActAmount(a)});
 let cumulative=0;const points=Object.entries(byDate).map(([date,v])=>({date,value:cumulative+=v}));
 const maxCum=Math.max(1,...points.map(x=>x.value));
 const line=points.length?`<div class="finTimeline">${points.map((p,i)=>`<div class="finPoint"><div class="finPointBar" style="height:${Math.max(3,p.value/maxCum*100)}%"></div><b>${money(p.value)}</b><small>${esc(p.date)}</small></div>`).join("")}</div>`:'<div class="empty">Добавьте акты с датами — появится накопительный график.</div>';
 return card("График исполнения договоров",bars)+card("Накопительное закрытие по актам",line)
}
function financeView(){
 if(!financeUnlocked)return card("Финансы",'<div class="financeLock"><b>Раздел защищён паролем</b><p>Финансовые данные скрыты.</p><button class="btn" data-finance-unlock>Войти</button></div>');
 const cs=arr("financeContracts"),acts=arr("financeActs"),contractTotal=cs.reduce((z,c)=>z+financeContractTotal(c).total,0),closed=acts.reduce((z,a)=>z+financeActAmount(a),0),left=Math.max(0,contractTotal-closed);
 const analytics=card("Финансовая аналитика",`<div class="financeStats"><div><small>Сумма договоров</small><b>${money(contractTotal)}</b></div><div><small>Закрыто по актам</small><b>${money(closed)}</b></div><div><small>Осталось закрыть</small><b>${money(left)}</b></div><div><small>Выполнение</small><b>${contractTotal?Math.min(100,closed/contractTotal*100).toFixed(1):"0"}%</b></div></div>`);
 const detail=cs.length?`<div class="tableWrap"><table><thead><tr><th>Договор</th><th>Работы</th><th>Договорной объём</th><th>Закрыто</th><th>Остаток</th><th>Цена/ед.</th><th>Сумма без НДС</th><th>НДС</th><th>Всего</th><th>Закрыто, ₸</th><th>Осталось, ₸</th></tr></thead><tbody>${cs.map(c=>{const x=financeContractTotal(c),q=n(c.qty),cq=financeClosedQty(c.contract),ca=acts.filter(a=>(a.contract||"")===(c.contract||"")).reduce((z,a)=>z+financeActAmount(a),0);return `<tr><td><b>${esc(c.contract||"—")}</b></td><td>${esc(c.work||"—")}</td><td>${fmt(q)} ${esc(c.unit||"")}</td><td>${fmt(cq)} ${esc(c.unit||"")}</td><td>${fmt(Math.max(0,q-cq))} ${esc(c.unit||"")}</td><td>${money(c.price)}</td><td>${money(x.base)}</td><td>${n(c.vatRate)?n(c.vatRate)+"% · "+money(x.vatAmount):"Без НДС"}</td><td><b>${money(x.total)}</b></td><td>${money(ca)}</td><td><b>${money(Math.max(0,x.total-ca))}</b></td></tr>`}).join("")}</tbody></table></div>`:'<div class="empty">Добавьте договор.</div>';
 const contracts=card("Договоры",rowEditor("financeContracts",[["Договор","contract"],["Вид работ / предмет","work"],["Ед. изм. (тн, м², м³, шт.)","unit"],["Количество по договору","qty","number"],["Цена за 1 ед., ₸","price","number"],["НДС","vatRate","vat"]])+detail);
 const actCard=card("Акты выполненных работ",rowEditor("financeActs",[["Дата акта","date","date"],["Договор","contract","financecontract"],["№ акта","actNo"],["Закрытый объём","qty","number"],["Сумма акта с НДС, ₸","amount","number"]])+'<p class="hint">Если сумму акта оставить пустой, программа рассчитает её автоматически: закрытый объём × цена за единицу + НДС по договору.</p>');
 return analytics+financeCharts()+contracts+actCard+`<div class="financeActions"><button class="btn" data-finance-password>Изменить пароль</button><button class="danger" data-finance-lock>Закрыть раздел</button></div>`
}
function portfolioAnalytics(){
 const rows=(portfolioData||[]).filter(r=>r.data).map(r=>{const d=normalizeState(r.data),contracts=d.financeContracts||[],acts=d.financeActs||[],units={};
  const contractTotal=contracts.reduce((z,c)=>z+n(c.qty??c.quantity)*n(c.price)*(1+n(c.vat)/100),0);
  const closedMoney=acts.reduce((z,a)=>{const c=contracts.find(x=>(x.contract||"")===(a.contract||""));const auto=c?n(a.qty??a.quantity)*n(c.price)*(1+n(c.vat)/100):0;return z+n(a.amount||auto)},0);
  for(const t of d.tasks||[]){const u=String(t.unit||"ед.").trim()||"ед.",vol=n(t.volume??t.qty??t.quantity),done=(d.workDays||[]).filter(x=>(x.type||"")===(t.type||"")&&(x.code||"")===(t.code||"")).reduce((z,x)=>z+qtyOf(x)*rowPerState(d,x),0);units[u]??={project:0,done:0};units[u].project+=vol;units[u].done+=done}
  const project=Object.values(units).reduce((z,x)=>z+x.project,0),weighted=Object.values(units).reduce((z,x)=>z+(x.project?Math.min(1,x.done/x.project)*x.project:0),0),pct=project?weighted/project*100:0;
  return{id:r.id,name:r.name||d.object||"Без названия",contractTotal,closedMoney,remaining:Math.max(0,contractTotal-closedMoney),pct,units}
 });
 const ct=rows.reduce((z,x)=>z+x.contractTotal,0),cm=rows.reduce((z,x)=>z+x.closedMoney,0),rem=Math.max(0,ct-cm),allUnits={};
 for(const x of rows)for(const [u,v] of Object.entries(x.units)){allUnits[u]??={project:0,done:0};allUnits[u].project+=v.project;allUnits[u].done+=v.done}
 const unitCards=Object.entries(allUnits).map(([u,v])=>`<div class="portfolioUnit"><b>${esc(u)}</b><span>Проект: ${fmt(v.project)}</span><span>Выполнено: ${fmt(v.done)}</span><span>Осталось: ${fmt(Math.max(0,v.project-v.done))}</span></div>`).join("");
 const maxMoney=Math.max(1,...rows.map(x=>x.contractTotal));
 const charts=rows.length?`<div class="portfolioCharts"><div class="portfolioChart"><h3>Выполнение по объектам</h3>${rows.map(x=>`<div class="portfolioChartRow"><span title="${esc(x.name)}">${esc(x.name)}</span><div><i style="width:${Math.min(100,x.pct)}%"></i></div><b>${fmt(x.pct)}%</b></div>`).join("")}</div><div class="portfolioChart money"><h3>Финансы по объектам</h3>${rows.map(x=>{const closed=x.contractTotal?Math.min(100,x.closedMoney/x.contractTotal*100):0,total=x.contractTotal/maxMoney*100;return `<div class="portfolioMoneyRow"><span title="${esc(x.name)}">${esc(x.name)}</span><div class="moneyScale" style="width:${Math.max(4,total)}%"><i style="width:${closed}%"></i></div><b>${fmt(x.closedMoney)} / ${fmt(x.contractTotal)} ₸</b></div>`}).join("")}</div></div>`:"";
 return `<div class="portfolioAnalytics"><div class="stats portfolioStats"><b>Общая сумма: ${fmt(ct)} ₸</b><b>Закрыто: ${fmt(cm)} ₸</b><b>Осталось: ${fmt(rem)} ₸</b></div>${unitCards?`<div class="portfolioUnits">${unitCards}</div>`:""}${charts}${rows.length?`<table><thead><tr><th>Объект</th><th>Выполнение</th><th>Физические объёмы</th><th>Сумма</th><th>Закрыто</th><th>Остаток</th></tr></thead><tbody>${rows.map(x=>`<tr><td><button class="portfolioObjectLink" data-report-open="${x.id}">${esc(x.name)}</button></td><td><div class="portfolioProgress"><i style="width:${Math.min(100,x.pct)}%"></i></div><small>${fmt(x.pct)}%</small></td><td>${Object.entries(x.units).map(([u,v])=>`<div><b>${esc(u)}:</b> ${fmt(v.done)} / ${fmt(v.project)} · ост. ${fmt(Math.max(0,v.project-v.done))}</div>`).join("")||"—"}</td><td>${fmt(x.contractTotal)} ₸</td><td>${fmt(x.closedMoney)} ₸</td><td>${fmt(x.remaining)} ₸</td></tr>`).join("")}</tbody></table>`:'<div class="empty">Для аналитики добавьте данные по объектам.</div>'}</div>`
}
function rowPerState(d,x){if(n(x.per)>0)return n(x.per);const t=(d.tasks||[]).find(t=>(t.type||"")===(x.type||"")&&(t.code||"")===(x.code||""));const b=(t?.bom||[]).find(b=>normMark(b.mark)===normMark(x.mark));return b?perFor(t,b):1}
function reportsScreen(){
 const rows=reportList.map(r=>`<div class="reportTile"><div><b>${esc(r.name||"Без названия")}</b><small>Изменён: ${esc(r.updated||"—")}</small>${currentReportId===r.id?'<em class="reportCurrent">Текущий отчёт</em>':""}</div><div><button class="btn" data-report-open="${r.id}">Открыть</button><button data-report-dup="${r.id}">Дублировать</button><button class="danger" data-report-del="${r.id}">Удалить</button></div></div>`).join("");
 return card("Аналитика по всем объектам",portfolioAnalytics())+card("Мои отчёты",`<div class="reportDashboardHead"><div><b>${reportList.length}</b><span>отчётов в программе</span></div><input id="reportSearch" placeholder="Поиск по названию объекта"></div><div class="reportCreate"><input id="newReportName" placeholder="Название нового объекта / отчёта"><button class="btn" data-report-create>+ Создать отчёт</button></div><div class="reportTiles">${rows||'<div class="empty">Отчётов пока нет.</div>'}</div>`)
}
async function refreshReports(){reportList=await ATemir.reports()||[];portfolioData=await ATemir.reportAnalytics()||[]}
async function openReport(id){const next=+id;if(!next)return;if(currentReportId&&currentReportId!==next)await flushSave();const d=await ATemir.load(next);if(!d){alert("Не удалось открыть отчёт.");await refreshReports();view="reports";render();return}currentReportId=next;state=normalizeState(d);hydrateRowUnits();financeUnlocked=false;view="home";render()}
function render(){if(view==="reports"){$("#nav").innerHTML="";$("#title").textContent="Мои отчёты";$("#obj").textContent="Выберите объект";$("#companyBrand").textContent="ОТЧЁТЫ СМР";document.title="Мои отчёты — Отчет строительно-монтажных работ";$("#saveReport").disabled=true;$("#bak").disabled=true;$("#html").disabled=true;$("#pdf").disabled=true;$("#content").innerHTML=reportsScreen();return}$("#saveReport").disabled=false;$("#bak").disabled=false;$("#html").disabled=false;$("#pdf").disabled=false;$("#nav").innerHTML=views.map(x=>`<button data-v="${x[0]}" class="${view===x[0]?"active":""} ${x[0]==="manage"?"manageNav":""}">${x[1]}</button>`).join("");$("#title").textContent=views.find(x=>x[0]===view)?.[1]||"Отчёт";$("#obj").textContent=state.object||state.objectName||"Новый объект";$("#companyBrand").textContent=state.companyName||"КОМПАНИЯ";document.title="Отчет строительно-монтажных работ"+(state.companyName?" — "+state.companyName:"");const c=$("#content");
 if(view==="home")c.innerHTML=home();else if(view==="progress")c.innerHTML=summary();else if(view==="works")c.innerHTML=groupedWorksView();else if(view==="bom")c.innerHTML=bomView();else if(view==="invoices")c.innerHTML=groupedInvoicesView();else if(view==="people")c.innerHTML=card("Ответственные / работники",table([...arr("responsibles"),...arr("workers")],[["ФИО",r=>r.name||r.fio],["Должность","position"]]));else if(view==="machines")c.innerHTML=card("Машины и механизмы",table(arr("equipment"),[["Наименование",r=>r.name||r.title],["Количество",r=>r.qty||r.quantity]]));else if(view==="dynamics")c.innerHTML=dynamicsView();else if(view==="deadlines")c.innerHTML=ganttView();else if(view==="acted")c.innerHTML=card("Актированные дни",table(arr("actedDays"),[["Дата",r=>r.date||r],["Причина",r=>r.reason||r.text||""],["Значение",r=>r.value||""],["Время",r=>r.time||""]]))+multiCalendarView();else if(view==="penalties")c.innerHTML=penaltiesView();else if(view==="finance")c.innerHTML=financeView();else c.innerHTML=management();
}
$("#nav").onclick=async e=>{const b=e.target.closest("[data-v]");if(b){if(b.dataset.v==="finance"&&!(await unlockFinance()))return;view=b.dataset.v;render()}};
$("#content").onclick=async e=>{
 const ro=e.target.closest("[data-report-open]");if(ro){await openReport(ro.dataset.reportOpen);return}
 const rc=e.target.closest("[data-report-create]");if(rc){const inp=$("#newReportName"),name=(inp?.value||"").trim()||"Новый отчёт";const id=await ATemir.createReport(name);await refreshReports();await openReport(id);return}
 const rd=e.target.closest("[data-report-dup]");if(rd){const source=+rd.dataset.reportDup;if(currentReportId===source)await flushSave();const id=await ATemir.duplicateReport(source);if(!id){alert("Не удалось создать копию отчёта.");return}await refreshReports();await openReport(id);return}
 const rx=e.target.closest("[data-report-del]");if(rx){const id=+rx.dataset.reportDel;if(reportList.length<=1){alert("Нельзя удалить единственный отчёт. Сначала создайте другой.");return}if(!confirm("Удалить этот отчёт? Действие нельзя отменить."))return;await ATemir.deleteReport(id);if(currentReportId===id){currentReportId=null;const left=(await ATemir.reports()||[])[0];if(left){currentReportId=left.id;state=normalizeState(await ATemir.load(left.id)||{});hydrateRowUnits()}}await refreshReports();view="reports";render();return}const fu=e.target.closest("[data-finance-unlock]");if(fu){if(await unlockFinance())render();return}const fl=e.target.closest("[data-finance-lock]");if(fl){financeUnlocked=false;render();return}const fp=e.target.closest("[data-finance-password]");if(fp){const p=prompt("Новый пароль:");if(!p)return;const p2=prompt("Повторите новый пароль:");if(p!==p2){alert("Пароли не совпадают.");return}state.financePasswordHash=await hashPassword(p);await save(true);alert("Пароль изменён.");return}const er=e.target.closest("[data-edit-row]");if(er){editingRows[er.dataset.editRow]=+er.dataset.i;render();return}const cp=e.target.closest("[data-copy-row]");if(cp){const key=cp.dataset.copyRow,i=+cp.dataset.i,copy={...arr(key)[i]};arr(key).splice(i+1,0,copy);editingRows[key]=i+1;await save(true);render();return}const rs=e.target.closest("[data-row-save]");if(rs){await save(true);delete editingRows[rs.dataset.rowSave];render();return}const bf=e.target.closest("[data-bom-filter]");if(bf){bomFilter=bf.dataset.bomFilter;render();return}const lb=e.target.closest("[data-lightbox]");if(lb){const box=document.createElement("div");box.className="lightbox";box.innerHTML='<button aria-label="Закрыть">×</button><img src="'+lb.src+'">';box.onclick=()=>box.remove();document.body.appendChild(box);return}const bi=e.target.closest("[data-bom-import]");if(bi){try{const res=await ATemir.importBOM();if(res){const t=arr("tasks")[+bi.dataset.bomImport];t.bom=res.rows;t.bomName=res.file||res.sheet||"Excel";await save(true);render();alert("Ведомость загружена: "+res.rows.length+" марок.")}}catch(err){alert("Ошибка Excel: "+err.message)}return}const pa=e.target.closest("[data-photo-add]");if(pa){const imgs=await ATemir.choosePhotos();if(imgs?.length){state.reportPhotos=[...arr("reportPhotos"),...imgs].slice(0,12);await save(true);render()}return}const pd=e.target.closest("[data-photo-del]");if(pd){arr("reportPhotos").splice(+pd.dataset.photoDel,1);await save(true);render();return}const pc=e.target.closest("[data-photo-clear]");if(pc){state.reportPhotos=[];await save(true);render();return}const ll=e.target.closest("[data-logo-load]");if(ll){const data=await ATemir.chooseLogo();if(data){state.companyLogo=data;await save(true);render()}return}const lr=e.target.closest("[data-logo-remove]");if(lr){state.companyLogo="";await save(true);render();return}const m=e.target.closest("[data-mv]");if(m){manageView=m.dataset.mv;render();return}const a=e.target.closest("[data-add]");if(a){state[a.dataset.add]=arr(a.dataset.add);state[a.dataset.add].push({});editingRows[a.dataset.add]=state[a.dataset.add].length-1;await save(true);render();return}const d=e.target.closest("[data-del]");if(d){if(!confirm("Удалить эту запись?"))return;arr(d.dataset.del).splice(+d.dataset.i,1);delete editingRows[d.dataset.del];await save(true);render();return}const cr=e.target.closest("[data-clear-report]");if(cr){if(!confirm("Очистить данные этого отчёта? Объект и реквизиты компании останутся."))return;cr.disabled=true;for(let i=3;i>0;i--){cr.textContent=`Подтвердить через ${i} сек.`;await new Promise(r=>setTimeout(r,1000))}if(!confirm("ТОЧНО очистить данные отчёта? Восстановить их без резервной копии будет нельзя.")){render();return}const keep={companyName:state.companyName,object:state.object,address:state.address,client:state.client,companyLogo:state.companyLogo,reportSections:state.reportSections,financePasswordHash:state.financePasswordHash};state=normalizeState(keep);await save(true);render();alert("Данные отчёта очищены.");return}};
$("#content").oninput=async e=>{if(e.target.id==="reportSearch"){const q=e.target.value.trim().toLowerCase();document.querySelectorAll(".reportTile").forEach(x=>x.style.display=!q||x.textContent.toLowerCase().includes(q)?"":"none");return}if(e.target.dataset.root){state[e.target.dataset.root]=e.target.value}else if(e.target.dataset.weather){state.weather=state.weather||{};state.weather[e.target.dataset.weather]=e.target.value}else if(e.target.dataset.list){const r=arr(e.target.dataset.list)[+e.target.dataset.i];r[e.target.dataset.k]=e.target.value}save();$("#obj").textContent=state.object||"Новый объект";$("#companyBrand").textContent=state.companyName||"КОМПАНИЯ"};
$("#reportsBtn").onclick=async()=>{if(currentReportId)await flushSave();await refreshReports();view="reports";render()};
$("#saveReport").onclick=async()=>{try{await save(true);const b=$("#saveReport"),old=b.textContent;b.textContent="Сохранено ✓";b.classList.add("saved");setTimeout(()=>{b.textContent=old;b.classList.remove("saved")},1400)}catch(e){alert("Ошибка сохранения: "+e.message)}};
function cleanReportHTML(){
 const title=esc(state.object||"Отчёт"),company=esc(state.companyName||""),client=esc(state.client||""),address=esc(state.address||""),date=esc(state.reportDate||"");
 return `<!doctype html><html lang="ru"><head><meta charset="utf-8"><title>${title}</title><style>
 @page{size:A4;margin:11mm 10mm 12mm}*{box-sizing:border-box}body{font-family:Arial,sans-serif;margin:0;color:#183247;background:#fff;font-size:10px}
 .printHead{display:grid;grid-template-columns:1fr auto;gap:14px;align-items:start;border-bottom:3px solid #123e63;padding-bottom:10px;margin-bottom:14px}.printHead h1{font-size:20px;line-height:1.15;margin:3px 0 5px}.printCompany{font-size:12px;font-weight:800;color:#123e63}.printMeta{font-size:9px;color:#5d7180;line-height:1.5}.printDate{border-left:4px solid #f2b318;background:#f3f6f8;padding:8px 10px;font-weight:700;white-space:nowrap}
 h2{font-size:13px;margin:0}.card{margin:0 0 12px;break-inside:avoid;border:1px solid #dce4ea}.card h2{padding:8px 9px;border-bottom:1px solid #dce4ea;position:relative}.card h2:after{content:"";position:absolute;left:9px;bottom:-1px;width:38px;height:3px;background:#f2b318}.body{padding:9px}
 table{width:100%;border-collapse:collapse;font-size:9px}th,td{border:1px solid #ccd6de;padding:5px 6px;vertical-align:top}th{background:#eaf0f4;color:#29465e;text-align:left}tr{break-inside:avoid}
 .photoCollage{display:grid;grid-template-columns:repeat(3,1fr);grid-auto-rows:105px;gap:5px}.photoCollage img{width:100%;height:100%;object-fit:cover}
 .stats,.financeStats{display:flex;gap:6px;flex-wrap:wrap}.stats b,.financeStats>div{padding:6px 8px;border-left:3px solid #f2b318;background:#eef3f7}
 .bars{height:160px;display:flex;align-items:flex-end;gap:3px;overflow:hidden;border-bottom:1px solid #cbd6df;padding:15px 3px 23px}.barCol{height:100%;min-width:25px;display:flex;flex-direction:column;justify-content:flex-end;align-items:center}.barCol i{display:block;width:70%;min-height:2px;background:#123e63}.barCol small,.barCol span{font-size:6px}
 .gantt{break-inside:avoid;border:1px solid #d7e0ea;border-left:4px solid #1769aa;padding:7px;margin:6px 0}.gantt.behind{border-left-color:#c62828}.gantt.ahead{border-left-color:#2e7d32}.gTrack{height:16px;background:#dfe8f0;position:relative}.gFact{display:block;height:100%;background:#1769aa}.gToday{position:absolute;top:-3px;bottom:-3px;width:2px;background:#e0a800}
 .calendar{display:grid;grid-template-columns:repeat(7,1fr);gap:2px}.calDay{min-height:25px;border:1px solid #d9dee7;padding:3px}.calDay.work{background:#dff4e5}.calDay.acted{background:#fbe0e0}.calDay.both{background:linear-gradient(135deg,#dff4e5 0 50%,#fbe0e0 50%)}
 .multiCalendar{display:grid;grid-template-columns:repeat(3,1fr);gap:5px}.monthCard{break-inside:avoid;border:1px solid #dce3ec;padding:5px}.monthCard h3{text-align:center;font-size:10px;margin:2px 0 5px}
 .reportGroup{border:1px solid #dce3ec;margin:5px 0;break-inside:avoid}.reportGroup summary{padding:6px 7px;font-weight:700}.reportGroup>*{display:block!important}.reportLogo{padding:0 0 8px}.reportLogo img{max-width:190px;max-height:70px}.bomFilters,.photoTools,.financeActions,.lightbox,button{display:none!important}.empty{color:#777;font-size:9px;padding:8px}
 .finTrack{height:15px;background:#e7edf2;display:flex}.finClosed{background:#1769aa}.finLeft{background:#f2b318}.finLegend{display:flex;gap:12px;font-size:8px}.finTimeline{height:150px;display:flex;align-items:flex-end;gap:5px}.finPoint{height:100%;min-width:50px;display:flex;flex-direction:column;justify-content:flex-end;align-items:center}.finPointBar{width:22px;background:#1769aa}.finPoint b,.finPoint small{font-size:6px}
 </style></head><body><div class="printHead"><div>${company?'<div class="printCompany">'+company+'</div>':""}<h1>${title}</h1><div class="printMeta">${client?'Заказчик: '+client+'<br>':""}${address?'Адрес: '+address:""}</div></div>${date?'<div class="printDate">Отчёт на '+date+'</div>':""}</div>${home()}</body></html>`
}
$("#imp").onclick=async()=>{try{const d=await ATemir.importJSON();if(!d)return;const name=d.object||d.objectName||"Импортированный отчёт";if(view==="reports"||!currentReportId){const id=await ATemir.createReport(name);currentReportId=id;state=normalizeState(d);hydrateRowUnits();await save(true);await refreshReports();view="home";render();alert("SaveFiles импортирован как новый отчёт.");return}if(!confirm("Импорт заменит данные текущего отчёта «"+(state.object||"Без названия")+"». Продолжить?"))return;state=normalizeState(d);hydrateRowUnits();await save(true);await refreshReports();render();alert("SaveFiles импортирован в текущий отчёт.")}catch(e){alert("Ошибка импорта: "+e.message)}};
$("#bak").onclick=()=>{if(!currentReportId){alert("Сначала откройте отчёт.");return}ATemir.backup(state)};
$("#pdf").onclick=()=>{if(!currentReportId){alert("Сначала откройте отчёт.");return}ATemir.pdf(cleanReportHTML())};
$("#html").onclick=()=>{if(!currentReportId){alert("Сначала откройте отчёт.");return}ATemir.exportHTML(cleanReportHTML())};
(async()=>{await refreshReports();if(reportList.length){currentReportId=reportList[0].id;const d=await ATemir.load(currentReportId);state=normalizeState(d?{...state,...d}:state);hydrateRowUnits();render()}else{view="reports";render()}})().catch(e=>alert("Ошибка запуска: "+e.message));
window.addEventListener("blur",()=>flushSave());
window.addEventListener("beforeunload",()=>{try{flushSave()}catch(e){}});

$("#content").onchange=async e=>{if(e.target.dataset.section){state.reportSections=state.reportSections||{};state.reportSections[e.target.dataset.section]=e.target.checked;await save(true);render();return}if(e.target.dataset.list){const key=e.target.dataset.list,r=arr(key)[+e.target.dataset.i],k=e.target.dataset.k;if(r){r[k]=e.target.value;
 if(k==="type"){r.code="";r.mark="";r.name="";r.weight1="";r.remaining="";r.totalWeight="";r.per=""}
 if(k==="code"){r.mark="";r.name="";r.weight1="";r.remaining="";r.totalWeight="";r.per=""}
 if(k==="mark"&&(key==="workDays"||key==="invoices")){const task=arr("tasks").find(t=>(t.type||"")===(r.type||"")&&(t.code||"")===(r.code||"")),b=(task?.bom||[]).find(x=>normMark(x.mark)===normMark(r.mark));if(b){r.name=b.name||"";r.weight1=n(b.weight1||b.weight);r.unit=task.unit||"шт";r.per=perFor(task,b);if(key==="workDays")r.remaining=Math.max(0,n(b.qty??b.quantity)-usedMark(r.type||"",r.code||"",r.mark)+qtyOf(r));r.totalWeight=qtyOf(r)*n(r.weight1)}}
 if(k==="qty"&&(key==="workDays"||key==="invoices")){const task=arr("tasks").find(t=>(t.type||"")===(r.type||"")&&(t.code||"")===(r.code||"")),b=(task?.bom||[]).find(x=>normMark(x.mark)===normMark(r.mark));if(b){r.per=perFor(task,b);if(key==="workDays"){const max=Math.max(0,n(b.qty??b.quantity)-usedMark(r.type||"",r.code||"",r.mark)+qtyOf(r));if(qtyOf(r)>max)r.qty=max;r.remaining=Math.max(0,max-qtyOf(r))}r.totalWeight=qtyOf(r)*n(r.weight1)}}
 await save(true);if(["type","code","mark","qty"].includes(k))render()}}};
